/**
 * Where Kimi keeps its data, shared by the Kimi usage, session and new
 * session code so they agree on one folder each. Owned by the architect:
 * implementers import these and do not edit this file (ask the integrator).
 */
import os from 'node:os';
import path from 'node:path';

import { resolveDir } from '../kit';
import { PluginConfig } from '../types';

/**
 * The Kimi Code CLI home: the `kimiDir` setting, else $KIMI_CODE_HOME, else
 * ~/.kimi-code (sessions/, credentials/, config.toml, bin/kimi).
 */
export function kimiCodeHome(
  config: PluginConfig | null | undefined,
  env: NodeJS.ProcessEnv = process.env,
  home: string = os.homedir()
): string {
  return resolveDir(
    config?.kimiDir,
    env.KIMI_CODE_HOME,
    path.join(home, '.kimi-code'),
    home
  );
}

/**
 * The Kimi desktop app's data folder (Electron userData of "kimi-desktop"):
 * the `kimiDesktopDir` setting, else the platform default.
 */
export function kimiDesktopDir(
  config: PluginConfig | null | undefined,
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
  home: string = os.homedir()
): string {
  let fallback: string;
  if (platform === 'darwin') {
    fallback = path.join(
      home,
      'Library',
      'Application Support',
      'kimi-desktop'
    );
  } else if (platform === 'win32') {
    fallback = path.join(
      env.APPDATA || path.join(home, 'AppData', 'Roaming'),
      'kimi-desktop'
    );
  } else {
    fallback = path.join(
      env.XDG_CONFIG_HOME || path.join(home, '.config'),
      'kimi-desktop'
    );
  }
  return resolveDir(config?.kimiDesktopDir, undefined, fallback, home);
}
